-- Source-verified Brazilian club jersey offers (catalog snapshots, 2026-11-23).
-- Only photograph the precise SKU. Actual CoreMotion checkout still uses test payments.
INSERT INTO public.external_offers
(id,title,description,store_name,category,sport,price,original_price,image_url,source_url,image_urls,variant_options,team_id,is_active)
SELECT v.* FROM (VALUES
('verified-br-flamengo-basquete-adidas-ii-2627', 'Regata Flamengo Basquete Adidas II 2026/27 Masculina Branca', 'Regata Flamengo Basquete Adidas II da temporada 2026/27, branca, 100% poliéster, sem numeração, escudo bordado. Preço de referência consultado na Centauro em 23/11/2026; disponibilidade e entrega dependem do fornecedor.', 'Esporte Legal via Centauro', 'Vestuário', 'Basquete', 379.9, 399.9, 'https://imgcentauro-a.akamaihd.net/1500x1500/M19EPQ01A1.jpg', 'https://www.centauro.com.br/camiseta-regata-do-flamengo-basquete-adidas-ii-26-27-masculina-m19epq-mktp.html?cor=01', ARRAY['https://imgcentauro-a.akamaihd.net/1500x1500/M19EPQ01A1.jpg']::text[], ARRAY['P','M','G','GG','2GG','3GG']::text[], 'nbb-brasil-2026-27:flamengo', true),
('verified-br-franca-larulp-jogador-vermelha', 'Regata Sesi Franca Basquete Larulp Jogador Vermelha Masculina', 'Regata oficial de jogo Sesi Franca Basquete Larulp, modelo masculino vermelho. Preço de referência de R$ 432,31 na Centauro em 23/11/2026. A temporada do modelo não é confirmada na loja e não foi presumida.', 'Total Tennis via Centauro', 'Vestuário', 'Basquete', 432.31, 469.9, 'https://imgcentauro-a.akamaihd.net/240x240/M17WG806A1.jpg', 'https://www.centauro.com.br/regata-larulp-sesi-franca-basquete-jogador-vermelho-masculino-m17wg8-mktp.html', ARRAY['https://imgcentauro-a.akamaihd.net/240x240/M17WG806A1.jpg']::text[], ARRAY['P','M','G']::text[], 'nbb-brasil-2026-27:sesi-franca', true),
('verified-br-botafogo-basket-jogo3-2526', 'Regata Botafogo Basquete Jogo 3 2025/26 Preta', 'Regata oficial Jogo 3 da coleção Botafogo Basquete 2025/26, preta com detalhes brancos. Foto correspondente à SKU anunciada na Botafogo Store. Preço regular de R$ 249,90 consultado em 23/11/2026, sem desconto exclusivo para sócios.', 'Botafogo Store', 'Vestuário', 'Basquete', 249.9, NULL, 'https://botafogo.vtexassets.com/arquivos/ids/167643-800-800?aspect=true&height=800&v=638960681133800000&width=800', 'https://store.botafogo.com.br/regata-botafogo-basquete-jogo-3-2526-/p', ARRAY['https://botafogo.vtexassets.com/arquivos/ids/167643-800-800?aspect=true&height=800&v=638960681133800000&width=800']::text[], ARRAY['P','M','G','GG','XG','XXG']::text[], 'nbb-brasil-2026-27:botafogo', true)
) AS v(id,title,description,store_name,category,sport,price,original_price,image_url,source_url,image_urls,variant_options,team_id,is_active)
WHERE EXISTS (SELECT 1 FROM public.catalog_teams c WHERE c.id=v.team_id)
AND NOT EXISTS (SELECT 1 FROM public.external_offers e WHERE e.id=v.id OR e.source_url=v.source_url)
ON CONFLICT (id) DO NOTHING;
